  for (const t of p.archive) appendBoard('ticket.archived', { id: t.id, reason: `a restart of #${run} ended the unfinished work` }, { actor: opts.actor, path: opts.path })
  return { cancelled, archived: p.archive.map((t) => t.id) }
}

